CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'USER', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE plants (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, code VARCHAR(80) NOT NULL, crop VARCHAR(80) NOT NULL, variety VARCHAR(120), planting_date DATE, location_label VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_plant_owner_code(owner_id, code), CONSTRAINT fk_plant_owner FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE observations (id BIGINT PRIMARY KEY AUTO_INCREMENT, plant_id BIGINT NOT NULL, observed_at TIMESTAMP NOT NULL, growth_stage VARCHAR(80) NOT NULL, soil_ph DECIMAL(4,2), soil_moisture DECIMAL(5,2), temperature_c DECIMAL(5,2), humidity_pct DECIMAL(5,2), irrigation_liters DECIMAL(8,2), image_reference VARCHAR(500), provenance VARCHAR(32) NOT NULL DEFAULT 'USER_RECORDED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_observation_plant FOREIGN KEY(plant_id) REFERENCES plants(id), INDEX ix_observation_plant_time(plant_id, observed_at));
CREATE TABLE predictions (id BIGINT PRIMARY KEY AUTO_INCREMENT, observation_id BIGINT NOT NULL, model_version VARCHAR(120) NOT NULL, status VARCHAR(32) NOT NULL, target_name VARCHAR(80) NOT NULL, predicted_value DECIMAL(10,3), unit VARCHAR(32), uncertainty DECIMAL(10,3), explanation VARCHAR(2000), request_id VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_prediction_observation FOREIGN KEY(observation_id) REFERENCES observations(id), INDEX ix_prediction_observation_time(observation_id, created_at));
CREATE TABLE harvest_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, plant_id BIGINT NOT NULL, harvested_at TIMESTAMP NOT NULL, brix DECIMAL(6,2), weight_g DECIMAL(8,2), firmness_n DECIMAL(8,2), provenance VARCHAR(32) NOT NULL DEFAULT 'USER_RECORDED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_harvest_plant FOREIGN KEY(plant_id) REFERENCES plants(id), INDEX ix_harvest_plant_time(plant_id, harvested_at));
